int GenericGameSaver::getInfo(int port, int slot, int *type, int *free, int *formatted)
{
  int cmd, result;
  int retry = 2;

  while (retry)
  {
    if (sceMcGetInfo(port, slot, type, free, formatted) != 0)
    {
      if (sceMcGetInfo(port, slot, type, free, formatted) != 0)
      {
        return -2;
      }
    }
    else if (sceMcSync(0, &cmd, &result) != 1)
    {
      return -2;
    }
    else
    {
      switch (result)
      {
        case -1: break;
        case -2: retry--;
        case 0:
          if (!*formatted)
          {
            if (retry == 2)
              retry--;
            else
            {
              return -1;
            }
            break;
          }
          if (!type)
          {
            return -5;
          }
          if (*type != 2)
          {
            return -4;
          }
          else return 0;
        break;
        default:
          if (retry == 2) retry--;
          else
          {
            return -5;
          }
      }
    }
    for (int stall=0; stall<100000; stall++) continue;
  }

  return 0;
}
